function i(n,s){const e=new Map;for(const t of n)s&&t.staff_id!==s||e.set(t.starts_at,[...e.get(t.starts_at)??[],t.staff_id]);return[...e].map(([t,a])=>({startsAt:t,staffIds:a}))}function r(n){return[...new Set(n.map(s=>s.staff_id))]}function f(n,s=6){const e=n?.suggested,t=Array.isArray(e)?e.filter(a=>typeof a=="string"):[];return[...new Set(t)].slice(0,s)}export{i as a,f as s,r as v};
